import hashlib,json,os,subprocess,tarfile
from pathlib import Path
root=Path(__file__).resolve().parents[4]; base=root/'.cache/compat-v010-published';base.mkdir(exist_ok=True)
def sha(b):return hashlib.sha256(b).hexdigest()
oldarchive=root/'dist/github-v0.1.0-assets/dircue_0.1.0_darwin_arm64.tar.gz'
assert sha(oldarchive.read_bytes())=='3eb328f168b321f6525a727f1a05b915cd53da522b649e06f9a8b5fad1abf87b'
binaries=[]
for name,archive in [('old',oldarchive),('new',root/'dist/release-0.2.0/dircue_0.2.0_darwin_arm64.tar.gz')]:
 with tarfile.open(archive) as f: content=f.extractfile('dircue').read()
 p=base/name;p.write_bytes(content);p.chmod(0o755);binaries.append(p)
flat=base/'flat';flat.mkdir(exist_ok=True)
for name,content in {'Main.cs':'// header\nclass Main {}\n','Main.java':'class Main {}\n','x.py':'print(1)\n','go.mod':'module sample\n\ngo 1.26\n','package.json':'{"dependencies":{"react":"19"}}\n','logs.xml':'<logs/>\n','README.md':'# readme\n','data.bin':'\x00x','generated.g.cs':'// <auto-generated>\nclass G {}\n','nested/Override.java':'class Forced {}\n','nested/.gitattributes':'Override.java linguist-language=C#\n','.gitattributes':'*.xml linguist-detectable=true\n'}.items():
 p=flat/name;p.parent.mkdir(exist_ok=True);p.write_text(content)
empty=base/'empty';empty.mkdir(exist_ok=True)
repo=base/'repo';repo.mkdir(exist_ok=True)
def git(*args):subprocess.run(['git',*args],cwd=repo,check=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
if not (repo/'.git').exists():
 git('init','-b','main');git('config','user.name','Compatibility Test');git('config','user.email','compat@example.invalid')
 for name in ['Main.cs','Main.java','x.py','go.mod','package.json','.gitattributes','logs.xml']:(repo/name).write_bytes((flat/name).read_bytes())
 git('add','.');git('commit','-m','base')
 (repo/'Main.java').write_text('class Changed {}\n');git('add','.');git('commit','-m','second')
 (repo/'Main.cs').write_text('class Dirty {}\n');(repo/'untracked.py').write_text('print(2)\n')
nohead=base/'nohead';nohead.mkdir(exist_ok=True)
if not (nohead/'.git').exists():subprocess.run(['git','init','-b','main',str(nohead)],check=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
(nohead/'Main.java').write_text('class Main {}\n')
cases=[]
for path in [flat,empty,repo,nohead]:
 for args in [[],['--json'],['-bj'],['--breakdown'],['--strategies'],['analyze','languages','--json'],['analyze','all','--json'],['analyze','all'],['analyze','ecosystems','--json'],['analyze','frameworks','--json'],['--source','directory','--json'],['--tree-size','1','--json'],['--max-file-bytes','10','--json'],['--workers','1','--json']]:cases.append((path,args))
for args in [['--rev','HEAD~1','--json'],['--source','git','--json'],['--source','git','--rev','not-a-revision','--json'],['--json','Main.cs'],['Main.java'],['-bjs','Main.java'],['--source','directory','--json','Main.cs'],['analyze','languages','--json','Main.cs']]:cases.append((repo,args))
for args in [['--json','missing'],['--source','bad','--json'],['--workers','-1'],['--workers','1025'],['--max-file-bytes','-1'],['--tree-size','0','--json'],['--tree-size','-1','--json'],['--unknown'],['--source'],['--workers','no'],['--rev','HEAD'],['--source','git','--json'],['--source','directory','--rev','HEAD'],['--json','Main.java'],['analyze','all','Main.java'],['analyze','languages','Main.java'],['--json','--','Main.java'],['--json','Main.java','x.py'],['-j','false']]:cases.append((flat,args))
# Root-level paths that share names with subcommands stay explicit when needed.
for name in ['analyze','metrics','-folder']:
 p=flat/name;p.mkdir(exist_ok=True);(p/'a.java').write_text('class A {}\n');cases.append((flat,['--json','--',name]))
rows=[]
for cwd,args in cases:
 runs=[]
 for exe in binaries:
  r=subprocess.run([str(exe),*args],cwd=cwd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=60)
  runs.append({'exit':r.returncode,'stdout':r.stdout.decode(),'stderr':r.stderr.decode()})
 equal=runs[0]==runs[1];rows.append({'cwd':str(cwd.relative_to(base)),'args':args,'equal':equal,'old':runs[0],'new':runs[1]})
extra=[]
for args in [['--version'],['--help'],['analyze'],['analyze','--help']]:
 runs=[subprocess.run([str(exe),*args],cwd=flat,capture_output=True,text=True) for exe in binaries]
 extra.append({'args':args,'old':{'exit':runs[0].returncode,'stdout':runs[0].stdout,'stderr':runs[0].stderr},'new':{'exit':runs[1].returncode,'stdout':runs[1].stdout,'stderr':runs[1].stderr}})
result={'old_published_asset_sha256':sha(oldarchive.read_bytes()),'binaries':{str(p.name):sha(p.read_bytes()) for p in binaries},'cases':rows,'intentional_interface_additions':extra,'exact_matches':sum(x['equal'] for x in rows),'total':len(rows)}
(base/'receipt.json').write_text(json.dumps(result,indent=2)+'\n')
print('exact',result['exact_matches'],'/',len(rows));print('differences',[(r['cwd'],r['args'],r['old'],r['new']) for r in rows if not r['equal']])
